"""Second, independent route for the a = 0 Koblitz orders: #E(F_2^n) = Norm(1 - alpha^n)
with alpha a root of T^2 + T + 2 in Z[w], w = (-1 + sqrt(-7))/2, computed by
binary exponentiation in the ring (not the linear recurrence).  Then the ladder
admission (order = 4 * prime) for the contract's n and a scan for admissible n."""
from sympy import isprime, factorint
# ring Z[w] with w^2 = -w - 2 ; elements (a, b) = a + b w ; alpha = w
def rmul(x, y):
    a, b = x; c, d = y
    # (a + b w)(c + d w) = ac + (ad + bc) w + bd w^2 = ac - 2bd + (ad + bc - bd) w
    return (a*c - 2*b*d, a*d + b*c - b*d)
def rpow(x, e):
    r = (1, 0)
    while e:
        if e & 1: r = rmul(r, x)
        x = rmul(x, x); e >>= 1
    return r
def norm(x):  # N(a + b w) = a^2 - ab + 2 b^2  (conj(w) = -1 - w)
    a, b = x; return a*a - a*b + 2*b*b
def order(n):
    an = rpow((0, 1), n); one_minus = (1 - an[0], -an[1]); return norm(one_minus)
for n in (17, 19, 23, 29, 31, 131):
    N = order(n); f = factorint(N) if n < 100 else None
    print("n=%3d #E=%d factor=%s  order/4 prime: %s" % (n, N, dict(f) if f else "(l checked separately)", N % 4 == 0 and (isprime(N // 4))))
print("n=131 equals 4*l:", order(131) == 4*680564733841876926932320129493409985129)
adm = [n for n in range(5, 64) if order(n) % 4 == 0 and isprime(order(n) // 4)]
print("n in [5,63] with #E = 4 * prime for the a = 0 Koblitz curve:", adm)

"""Two small synthetic checks (own code plus dry calls of two fixture functions on
integers; no curve, no cell, no experiment).
(1) The contract's shuffle definition 'group points into equal-marginal classes'
    needs a tolerance rule: with exact equality of sampled marginals a point-level
    shuffle is (nearly) a no-op; with a binned rule it destroys a homomorphism's
    reading and preserves a marginal-skew reading, as RT-EXP-1 intends.
(2) The fixture's own bootstrap_gain on a synthetic random label: the percentile
    interval sits above the point estimate (duplicated pairs inflate the max)."""
import sys, os, random, math
sys.path.insert(0, os.path.abspath("fixture")); import stage1_gate as fx
rng = random.Random(5); N, M, S = 100003, 16, 200000
pairs = []
while len(pairs) < S:
    P = rng.randrange(1, N); Q = rng.randrange(1, N); T = (P + Q) % N
    if T: pairs.append((P, Q, T))
hom = lambda P: P % M; skew = lambda P: 0 if P % 7 else (P // 7) % M
def binned_point_shuffle(pairs, h, M, rel_tol=0.05, seed=0):
    pts = sorted({R for t in pairs for R in t}); cnt = {}
    for R in pts: cnt[h(R)] = cnt.get(h(R), 0) + 1
    # bin buckets whose marginal frequencies agree within rel_tol (greedy on sorted frequencies)
    order = sorted(range(M), key=lambda b: cnt.get(b, 0)); classes = []; cur = [order[0]]
    for b in order[1:]:
        if abs(cnt.get(b, 0) - cnt.get(cur[0], 0)) <= rel_tol * max(1, cnt.get(cur[0], 0)): cur.append(b)
        else: classes.append(cur); cur = [b]
    classes.append(cur); cls_of = {b: i for i, c in enumerate(classes) for b in c}
    members = {}
    for R in pts: members.setdefault(cls_of[h(R)], []).append(R)
    r = random.Random(seed); new = {}
    for i, mem in members.items():
        vals = [h(R) for R in mem]; r.shuffle(vals)
        for R, v in zip(mem, vals): new[R] = v
    return (lambda R: new[R]), len(classes)
for name, h in (("mod-M label (homomorphism)", hom), ("skewed label (marginal artifact)", skew)):
    g = fx.bucket_gain(pairs, h, M)[0]
    hs, ncls = binned_point_shuffle(pairs, h, M)
    gs = fx.bucket_gain(pairs, hs, M)[0]
    print("  %-34s G=%.3f  G after binned point-level shuffle (%d classes)=%.3f" % (name, g, ncls, gs))
print("  reading: a correctly specified shuffle destroys the homomorphism reading (toward the null) and preserves the skew reading; the fixture's relabelling shuffle changes neither.")
# (2) fixture bootstrap_gain dry call on a synthetic random label
rl = fx.make_random_label(None, M, seed=99)
g0 = fx.bucket_gain(pairs, rl, M)[0]
lo, hi, w = fx.bootstrap_gain(pairs, rl, M, resamples=40, seed=1)
print("  fixture bootstrap_gain (40 resamples) on a random label, M=%d, S=%d, S/M^2=%d: point G=%.3f, percentile interval [%.3f, %.3f], contains 1: %s, contains the point estimate: %s" % (M, S, S // M**2, g0, lo, hi, lo <= 1 <= hi, lo <= g0 <= hi))
